      Lemma memI_x : forall m m2 st st2 ps (st2v : vstack) sz tot,
        memI m st ps sz tot ->
        xpres H REST SPA (vs_X pa) m m2 ->
        as_RHEAP H st2 (blocks_vs st2v ++ REST) m2 -> as_RFS H LF3 m2 -> bj_env_post H m2 spw tp lo B ->
        vs_at m2 pa st2v ->
        memI m2 st2 (mkPS st2v (ps_end ps) (ps_depth ps) (ps_ecset ps) (ps_more ps)) sz tot.
Proof.
