      Lemma call_flush : forall msF1 mo1 m st ps sz tot q (r : rv) (F1 : bvmap 5 word) (fc1 : bv 32) (c ret E : Z),
        as_VIS H st msF1 = MS (mkRr r) F1 (Z_to_bv 64 E) fc1 None m (seg_rom asegs) ->
        (E = A_PUSH_CHARS_S \/ E = A_PUSH_CHARS_K) ->
        as_AKREL H st (mkCfg msF1 mo1) -> as_MPRES H mo0 mo1 ->
        memI m st ps sz (tot + sz) -> psI ps tot -> a8I st ps q sz tot ->
        0 < sz <= 256 -> tot + sz <= 0x7ffffffe -> vs_n (ps_vs ps) + tot + sz + (e - q) < 2^26 -> q0 <= q <= e -> frm0 fc1 ->
        pecore r spw (bv_unsigned sp) ff c -> rgp r = gp -> rtp r = tp -> ra0 r = a0 -> ra1 r = Z_to_bv 64 (ff + 32) -> ra2 r = Z_to_bv 64 sz ->
        rra r = Z_to_bv 64 ret -> (ret = 0x107358 \/ ret = 0x107370 \/ ret = 0x107ae0 \/ ret = 0x107af4) ->
        (forall msF2 mo2 m2 st2 ps2 (r2 : rv),
            as_VIS H st2 msF2 = MS (mkRr r2) F1 (Z_to_bv 64 ret) fc1 None m2 (seg_rom asegs) ->
            as_AKREL H st2 (mkCfg msF2 mo2) -> as_MPRES H mo0 mo2 ->
            memI m2 st2 ps2 sz (tot + sz) -> psI ps2 (tot + sz) -> a8I st2 ps2 q 0 (tot + sz) -> vs_n (ps_vs ps2) = vs_n (ps_vs ps) ->
            pecore r2 spw (bv_unsigned sp) ff c -> rgp r2 = gp -> rtp r2 = tp -> rra r2 = Z_to_bv 64 ret -> ra0 r2 = Z_to_bv 64 1 ->
            rs3 r2 = rs3 r -> rs7 r2 = rs7 r -> rs11 r2 = rs11 r ->
            as_SR H POST (mkCfg msF2 mo2)) ->
        as_SR H POST (mkCfg msF1 mo1).
