      Lemma tail_failA : forall msF1 mo1 m st ps sz tot qa sza (r : rv) (p' : Z),
        as_VIS H st msF1 = MS (mkRr r) F (Z_to_bv 64 0xfa77c) fc None m (seg_rom asegs) ->
        as_AKREL H st (mkCfg msF1 mo1) -> as_MPRES H mo0 mo1 ->
        memI m st ps sz tot -> psI ps tot -> a8I st ps qa sza tot -> qa <= e -> tot <= 0x7ffffffe ->
        rsp r = spw -> rs1 r = spw -> rs0 r = Z_to_bv 64 (bv_unsigned sp) -> rs2 r = Z_to_bv 64 (sh8 ff) ->
        rgp r = gp -> rtp r = tp -> ra0 r = a0 ->
        ra1 r = Z_to_bv 64 p' -> q0 <= p' <= e -> bv_unsigned (ra2 r) <> 0 -> 2 <= bv_unsigned (ra3 r) ->
        (rra r = Z_to_bv 64 0x107fc8 \/ (rra r = Z_to_bv 64 0x108088 /\ rs3 r = Z_to_bv 64 ff)) ->
